194	  // instead, and a person asks for the fix. Failing the workflow step instead would
195	  // have written no check at all, which leaves the required context pending forever
196	  // — a pull request only a human can rescue, for a mistake an agent makes in the
197	  // ordinary course of editing its own tool surface.
198	  const deliverableProblems = input.deliverableProblems ?? [];
199	  if (deliverableProblems.length > 0) {
200	    const count = `${deliverableProblems.length} problem${deliverableProblems.length === 1 ? "" : "s"}`;
201	    return {
202	      verdict: "deliverable-invalid",
203	      summary:
204	        `.github/atomaton/ is not internally consistent (${count}), so CI was not run.` +
205	        `${askFor(engineerAgent)}`,
206	    };
207	  }
208	
209	  const normalised = conclusion.trim().toLowerCase();
210	  const passed = PASSING.has(normalised);
211	
212	  if (passed) {
213	    // The hold is the whole gate. A green verdict starts the standing request only
214	    // where a call is waiting for it: the ball with nobody yet, an ask nobody has
215	    // taken up, or the park whose collection this validation is. Everywhere else --
216	    // a run in flight (its own report is the thread's next word), a chain that
217	    // already carries the call, a turn a run handed back to a person -- the verdict
218	    // is delivered as a mention, and the person decides. This is the rule the
219	    // re-ask-the-asker routing replaced: a green run there re-started whoever made
220	    // the newest ask, call or no call, and its report was still being written when
221	    // the machinery started the next run over it.
222	    const hold = input.hold ?? { kind: "with-person" as const };
223	    if (hold.kind === "free" || hold.kind === "parked") {
224	      return { verdict: "passed", ...handTo(reviewerAgent), summary: `CI concluded ${normalised}.` };
225	    }
